def populate(packs, add):
    by_course={p['id']:p for p in packs}
    for raw in DATA.strip().splitlines():
        if not raw.strip():continue
        sid,title,teaching,parents,questions=raw.split('|',4)
        course,key=sid.split('.',1)
        extensions={'math01.uniform-continuity','math03.evolute','math05.gamma','math09.taylor',
                    'math09.least-squares','math10.parameter','math12.cauchy','theory.gyroscope',
                    'theory.variable-mass','materials.noncircular','materials.pressure-vessels',
                    'structures.advanced-buckling'}
        add(by_course[course],key,title,teaching,questions.replace(';;','\n'),
            prereq=parents.split(),aliases=[title],extended=sid in extensions)
        node=by_course[course]['skills'][-1]
        node['introduced_version']='0.2.0'
        node['learning_steps']=[part+'。' for part in teaching.rstrip('。').split('；')]
        node['aliases'] += {'math05.gamma':['Γ函数','伽马函数'],
                            'structures.gerber':['多跨静定梁','分层法','内铰','基本部分','附属部分'],
                            'materials.mohr':['莫尔圆','应力圆'],
                            'theory.impact':['恢复系数','碰撞'],
                            'structures.modal':['多自由度振动','振型']}.get(sid,[])
